      <g><g class="pin" data-id="cn" tabindex="0" role="button" aria-label="Trung Quốc: Mao lương"><circle class="hit" cx="1414.1" cy="265.6" r="22"/><circle class="dot" cx="1414.1" cy="265.6" r="7"/><text x="1414.1" y="249.6">Trung Quốc</text></g><g class="pin" data-id="nl" tabindex="0" role="button" aria-label="Hà Lan: Tulip"><circle class="hit" cx="923.8" cy="128.7" r="22"/><circle class="dot" cx="923.8" cy="128.7" r="7"/><text x="923.8" y="112.7">Hà Lan</text></g><g class="pin" data-id="ec" tabindex="0" role="button" aria-label="Ecuador: Hoa hồng"><circle class="hit" cx="509.3" cy="389.8" r="22"/><circle class="dot" cx="509.3" cy="389.8" r="7"/><text x="509.3" y="373.8">Ecuador</text></g><g class="pin" data-id="za" tabindex="0" role="button" aria-label="Nam Phi: Protea vua"><circle class="hit" cx="992.1" cy="559.6" r="22"/><circle class="dot" cx="992.1" cy="559.6" r="7"/><text x="992.1" y="543.6">Nam Phi</text></g><g class="pin" data-id="jp" tabindex="0" role="button" aria-label="Nhật Bản: Cúc zinnia"><circle class="hit" cx="1606.8" cy="174.7" r="22"/><circle class="dot" cx="1606.8" cy="174.7" r="7"/><text x="1606.8" y="158.7">Nhật Bản</text></g><g class="pin" data-id="my" tabindex="0" role="button" aria-label="Malaysia: Cúc mẫu đơn"><circle class="hit" cx="1406.9" cy="367.6" r="22"/><circle class="dot" cx="1406.9" cy="367.6" r="7"/><text x="1406.9" y="351.6">Malaysia</text></g><g class="pin" data-id="vn" tabindex="0" role="button" aria-label="Việt Nam: Lan hồ điệp"><circle class="hit" cx="1442.2" cy="330.3" r="22"/><circle class="dot" cx="1442.2" cy="330.3" r="7"/><text x="1442.2" y="314.3">Việt Nam</text></g><g class="pin" data-id="co" tabindex="0" role="button" aria-label="Colombia: Cẩm chướng"><circle class="hit" cx="529.7" cy="366.5" r="22"/><circle class="dot" cx="529.7" cy="366.5" r="7"/><text x="529.7" y="350.5">Colombia</text></g><g class="pin" data-id="nz" tabindex="0" role="button" aria-label="New Zealand: Mẫu đơn"><circle class="hit" cx="1763.2" cy="607.6" r="22"/><circle class="dot" cx="1763.2" cy="607.6" r="7"/><text x="1763.2" y="591.6">New Zealand</text></g></g>
