@push('styles')
<style>

:root{
  --bg:#F5EBE6; --ink:#5E4636; --soft:#8C6E5C; --copper:#C78E66; --deep:#A8714E;
  --dot:#DEC3AF; --card:#FCF8F5; --line:#E6D3C6; --shadow:rgba(120,80,55,.16);
  --sans:"Josefin Sans","Avenir Next","Century Gothic",system-ui,sans-serif;
  --serif:"Lora",Georgia,"Times New Roman",serif;
  box-sizing:border-box;
  padding-top:env(safe-area-inset-top,0px); padding-bottom:env(safe-area-inset-bottom,0px);
}
@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]){
    --bg:#221A16; --ink:#EEDFD4; --soft:#BFA493; --copper:#D9A47E; --deep:#E2B28E;
    --dot:#4B3B32; --card:#2D2420; --line:#433630; --shadow:rgba(0,0,0,.4);
  }
}
:root[data-theme="dark"]{
  --bg:#221A16; --ink:#EEDFD4; --soft:#BFA493; --copper:#D9A47E; --deep:#E2B28E;
  --dot:#4B3B32; --card:#2D2420; --line:#433630; --shadow:rgba(0,0,0,.4);
}
html{scroll-padding-top:env(safe-area-inset-top,0px)}
*,*::before,*::after{box-sizing:inherit}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased}
.about{max-width:1440px;margin:0 auto;padding:clamp(2.5rem,6vw,5.5rem) clamp(1.25rem,4vw,4rem);
  display:grid;grid-template-columns:minmax(0,5fr) minmax(0,8fr);gap:clamp(2rem,4vw,4.5rem);align-items:center}
.intro img{width:96px;height:auto;display:block;margin-bottom:2.2rem}
h1{font-weight:600;text-transform:uppercase;letter-spacing:.02em;line-height:1.02;
  font-size:clamp(2rem,3.3vw,3.3rem);color:var(--copper);margin:0 0 1.4rem}
.tag{font-family:var(--serif);font-style:italic;font-size:clamp(1.15rem,1.6vw,1.45rem);color:var(--deep);margin:0 0 1.2rem}
.lead{font-family:var(--serif);font-size:1.05rem;line-height:1.75;color:var(--soft);max-width:34em;margin:0}
.map-wrap{position:relative}
svg{width:100%;height:auto;display:block;overflow:visible}
.land{fill:var(--dot)}
.arc{fill:none;stroke:var(--copper);stroke-width:2.2;stroke-dasharray:1;stroke-dashoffset:1;opacity:.55;
  animation:draw 1.6s cubic-bezier(.6,.05,.3,1) forwards;animation-delay:calc(.4s + var(--d));transition:opacity .3s,stroke-width .3s}
.arc.on{opacity:1;stroke-width:3.6}
@keyframes draw{to{stroke-dashoffset:0}}
.pin{cursor:pointer;outline:none}
.pin .hit{fill:transparent}
.pin .dot{fill:var(--card);stroke:var(--copper);stroke-width:3;transition:r .25s,fill .25s}
.pin text{font-family:var(--sans);font-size:26px;font-weight:600;fill:var(--deep);text-anchor:middle;opacity:0;transition:opacity .25s;pointer-events:none;
  paint-order:stroke;stroke:var(--bg);stroke-width:7px}
.pin:hover .dot,.pin:focus-visible .dot,.pin.on .dot{fill:var(--copper);r:10}
.pin:hover text,.pin:focus-visible text,.pin.on text{opacity:1}
.pin:focus-visible .hit{stroke:var(--deep);stroke-width:2;stroke-dasharray:4 4}
.home circle.core{fill:var(--copper);transition:r .25s}.home.on circle.core{r:15}.home:focus-visible .hit{stroke:var(--deep);stroke-width:2;stroke-dasharray:4 4}
.card.home-card{border-radius:22px;background:var(--board,#3A2C24);background:#3A2C24}.card.home-card .c{color:#E2AE84}.card.home-card .f{color:#F4E8DC}.card.home-card .l{color:#CDB5A2}.card.home-card .r{color:#BFA493}
.card.home-card img{object-fit:cover;background:#F5EBE6}
.chips button.hn{font-weight:600}
.home circle.ring{fill:none;stroke:var(--copper);stroke-width:2;transform-origin:1429.2px 284.9px;transform-box:view-box;animation:pulse 2.6s ease-out infinite}
.home circle.ring:nth-of-type(2){animation-delay:1.3s}
@keyframes pulse{from{transform:scale(.6);opacity:.9}to{transform:scale(2.6);opacity:0}}
.home text{font-family:var(--sans);font-weight:600;font-size:28px;fill:var(--ink);paint-order:stroke;stroke:var(--bg);stroke-width:8px}
.card{position:relative;margin:1.2rem 0 0 6%;width:min(360px,100%);background:var(--card);border-radius:22px 22px 22px 4px;
  box-shadow:0 18px 40px -18px var(--shadow);padding:14px;display:grid;grid-template-columns:96px 1fr;gap:14px;align-items:center}
.card img{width:96px;height:96px;object-fit:cover;border-radius:50%;display:block}
.card .c{font-size:.82rem;letter-spacing:.08em;color:var(--copper);font-weight:600;margin:0 0 .15rem}
.card .f{font-family:var(--serif);font-size:1.35rem;margin:0;color:var(--ink);line-height:1.2}
.card .l{font-family:var(--serif);font-style:italic;font-size:.9rem;color:var(--soft);margin:.1rem 0 .35rem}
.card .r{font-size:.8rem;color:var(--soft);margin:0}
.card.swap{animation:swap .35s ease}
@keyframes swap{from{opacity:.2;transform:translateY(6px)}to{opacity:1;transform:none}}
.chips{display:flex;flex-wrap:wrap;gap:.5rem;margin:1.1rem 0 0 6%}
.chips button{font:inherit;font-size:.85rem;color:var(--deep);background:transparent;border:1.5px solid var(--line);border-radius:999px;padding:.45rem .9rem;cursor:pointer;transition:background .2s,border-color .2s,color .2s}
.chips button:hover{border-color:var(--copper)}
.chips button[aria-selected="true"]{background:var(--copper);border-color:var(--copper);color:var(--card)}
.chips button:focus-visible{outline:2px solid var(--deep);outline-offset:2px}
.stats{display:flex;gap:0;margin:2rem 0 0;max-width:34em}
.stats div{flex:1;padding:0 1.2rem;border-left:1.5px solid var(--line)}
.stats div:first-child{padding-left:0;border-left:0}
.stats b{display:block;font-family:var(--sans);font-weight:600;font-size:clamp(2rem,3.2vw,2.8rem);line-height:1;color:var(--copper);font-variant-numeric:tabular-nums}
.stats span{display:block;margin-top:.5rem;font-size:.78rem;letter-spacing:.12em;text-transform:uppercase;color:var(--soft)}
.passport{margin:1.6rem 0 0;max-width:34em;background:#3A2C24;color:#F4E8DC;border-radius:20px;padding:1.1rem 1.2rem 1rem;box-shadow:0 20px 40px -24px var(--shadow)}
.pp-head{display:flex;justify-content:space-between;align-items:center;font-weight:600;letter-spacing:.22em;font-size:.78rem;color:#E2AE84}
.pp-head span:last-child{letter-spacing:.08em;font-variant-numeric:tabular-nums;color:#F4E8DC;background:rgba(226,174,132,.16);border-radius:999px;padding:.25rem .65rem}
.pp-sub{margin:.4rem 0 .9rem;font-family:var(--serif);font-style:italic;font-size:.9rem;color:#CDB5A2}
.pp-grid{display:grid;grid-template-columns:repeat(9,minmax(0,1fr));gap:6px}
.st{aspect-ratio:1;border-radius:50%;border:1.5px dashed rgba(226,174,132,.45);display:grid;place-items:center;font-size:.6rem;letter-spacing:.06em;color:rgba(226,174,132,.55);font-weight:600;position:relative;cursor:pointer;background:none;font-family:inherit;padding:0}
.st:focus-visible{outline:2px solid #E2AE84;outline-offset:2px}
.st.on{border:2px solid #E2AE84;color:#F6E3D3;background:radial-gradient(circle at 35% 30%,#C98A66,#9A5A40 72%);transform:rotate(var(--r,-8deg))}
.st.on::after{content:"";position:absolute;inset:3px;border-radius:50%;border:1px solid rgba(246,227,211,.55)}
.st.pop{animation:stamp .55s cubic-bezier(.2,1.6,.4,1)}
@keyframes stamp{0%{transform:scale(1.9) rotate(-20deg);opacity:0}100%{transform:scale(1) rotate(var(--r,-8deg));opacity:1}}
.pp-reward{margin-top:1rem;border-top:1.5px dashed rgba(226,174,132,.35);padding-top:.9rem;animation:rise .6s ease}
@keyframes rise{from{opacity:0;transform:translateY(8px)}}
.pp-k{margin:0;font-size:.7rem;letter-spacing:.22em;color:#E2AE84;font-weight:600}
.pp-r{margin:.3rem 0 .7rem;font-family:var(--serif);font-size:1.05rem;color:#F4E8DC}
.pp-code{display:flex;gap:.5rem;align-items:center;flex-wrap:wrap}
.pp-code code{font-family:var(--sans);font-weight:600;letter-spacing:.14em;font-size:1rem;background:#F4E8DC;color:#5E4636;border-radius:10px;padding:.5rem .8rem;border:1.5px dashed #C78E66}
.pp-btn,.pp-reset{font:inherit;cursor:pointer;border-radius:999px}
.pp-btn{font-size:.82rem;background:#E2AE84;color:#2A1F19;border:0;padding:.55rem .9rem;font-weight:600}
.pp-tip{margin:.7rem 0 0;font-family:var(--serif);font-size:.92rem;color:#E9D9CB;min-height:1.3em}.pp-tip a{color:#E2AE84}
.pp-login{margin-top:.9rem;border-top:1.5px dashed rgba(226,174,132,.35);padding-top:.9rem}.pp-login p{margin:0 0 .7rem;font-family:var(--serif);font-style:italic;color:#CDB5A2}
a.pp-btn{text-decoration:none;display:inline-block}
.st.dim{opacity:.55}.pp-grid.locked .st{opacity:.3;pointer-events:none}
.pp-demo{margin-top:.9rem;display:flex;gap:.4rem;flex-wrap:wrap;align-items:center;font-size:.72rem;color:#BFA493;border-top:1px solid rgba(226,174,132,.2);padding-top:.7rem}
.pp-demo button{font:inherit;font-size:.72rem;color:#E2AE84;background:transparent;border:1px solid rgba(226,174,132,.4);border-radius:999px;padding:.3rem .6rem;cursor:pointer}
.pp-share{display:flex;gap:.5rem;flex-wrap:wrap;margin:.2rem 0 .8rem}.pp-btn.ghost{background:transparent;color:#E2AE84;border:1.5px solid rgba(226,174,132,.6)}
.pp-exp{margin:.5rem 0 .6rem;font-size:.78rem;color:#BFA493}
.pp-cta{color:#E2AE84;font-weight:600;font-size:.9rem;text-decoration:none}.pp-cta:hover{text-decoration:underline}
.pp-reset{display:block;margin:.8rem 0 0 auto;background:none;border:0;color:#9E8573;font-size:.74rem;text-decoration:underline;padding:0}
.pp-btn:focus-visible,.pp-reset:focus-visible,.pp-cta:focus-visible{outline:2px solid #E2AE84;outline-offset:2px}
@media (max-width:520px){.pp-grid{grid-template-columns:repeat(5,minmax(0,1fr))}}
.hint{font-size:.85rem;color:var(--soft);margin:1.6rem 0 0;display:flex;align-items:center;gap:.6rem}
.hint::before{content:"";width:10px;height:10px;border-radius:50%;border:2px solid var(--copper);background:var(--card)}
@media (max-width:860px){
  .about{grid-template-columns:1fr}
  .card{margin-left:0;width:100%}
  .chips{margin-left:0}
  .pin text{font-size:34px}
}
@media (prefers-reduced-motion:reduce){
  .arc{animation:none;stroke-dashoffset:0}
  .home circle.ring{animation:none;opacity:.35}
  .card.swap{animation:none}
}

</style>
@endpush

@push('scripts')
<script>
const DATA=[{"id": "hn", "country": "Hà Nội · Điểm đến", "flower": "Lâm Nhiên Thảo", "latin": "Nơi chín chuyến hoa cùng hạ cánh, được chăm chút rồi trao đến không gian của bạn.", "region": "Hà Nội", "lon": 105.85, "lat": 21.03, "coord": "21.03°N, 105.85°E", "img": "data:image/jpeg;base64,"}, {"id": "cn", "country": "Trung Quốc", "flower": "Mao lương", "latin": "Ranunculus asiaticus", "region": "Vân Nam", "lon": 102.83, "lat": 24.88, "coord": "24.88°N, 102.83°E", "img": "data:image/jpeg;base64,", "x": 1414.1499999999999, "y": 265.6}, {"id": "nl", "country": "Hà Lan", "flower": "Tulip", "latin": "Tulipa gesneriana", "region": "Aalsmeer", "lon": 4.76, "lat": 52.26, "coord": "52.26°N, 4.76°E", "img": "data:image/jpeg;base64,", "x": 923.8, "y": 128.70000000000002}, {"id": "ec", "country": "Ecuador", "flower": "Hoa hồng", "latin": "Rosa hybrida", "region": "Cayambe", "lon": -78.14, "lat": 0.04, "coord": "0.04°N, 78.14°W", "img": "data:image/jpeg;base64,", "x": 509.3, "y": 389.79999999999995}, {"id": "za", "country": "Nam Phi", "flower": "Protea vua", "latin": "Protea cynaroides", "region": "Western Cape", "lon": 18.42, "lat": -33.92, "coord": "33.92°S, 18.42°E", "img": "data:image/jpeg;base64,", "x": 992.1000000000001, "y": 559.6}, {"id": "jp", "country": "Nhật Bản", "flower": "Cúc zinnia", "latin": "Zinnia elegans", "region": "Hokkaido", "lon": 141.35, "lat": 43.06, "coord": "43.06°N, 141.35°E", "img": "data:image/jpeg;base64,", "x": 1606.75, "y": 174.7}, {"id": "my", "country": "Malaysia", "flower": "Cúc mẫu đơn", "latin": "Chrysanthemum morifolium", "region": "Cameron Highlands", "lon": 101.38, "lat": 4.47, "coord": "4.47°N, 101.38°E", "img": "data:image/jpeg;base64,", "x": 1406.9, "y": 367.65}, {"id": "vn", "country": "Việt Nam", "flower": "Lan hồ điệp", "latin": "Phalaenopsis", "region": "Đà Lạt", "lon": 108.44, "lat": 11.94, "coord": "11.94°N, 108.44°E", "img": "data:image/jpeg;base64,", "x": 1442.2, "y": 330.3}, {"id": "co", "country": "Colombia", "flower": "Cẩm chướng", "latin": "Dianthus caryophyllus", "region": "Sabana de Bogotá", "lon": -74.07, "lat": 4.71, "coord": "4.71°N, 74.07°W", "img": "data:image/jpeg;base64,", "x": 529.6500000000001, "y": 366.45000000000005}, {"id": "nz", "country": "New Zealand", "flower": "Mẫu đơn", "latin": "Paeonia lactiflora", "region": "Canterbury", "lon": 172.64, "lat": -43.53, "coord": "43.53°S, 172.64°E", "img": "data:image/jpeg;base64,", "x": 1763.1999999999998, "y": 607.65}];
const byId=Object.fromEntries(DATA.map(o=>[o.id,o]));
const card=document.getElementById('card');
const chips=document.getElementById('chips');
DATA.forEach(o=>{const b=document.createElement('button');if(o.id==='hn')b.className='hn';b.type='button';b.role='tab';b.dataset.id=o.id;b.textContent=o.country;b.addEventListener('click',()=>{show(o.id);if(CODES[o.id])explain(o.id)});chips.appendChild(b)});
function show(id){
  const o=byId[id]; if(!o) return;
  document.querySelectorAll('.pin').forEach(p=>p.classList.toggle('on',p.dataset.id===id));
  chips.querySelectorAll('button').forEach(b=>b.setAttribute('aria-selected',b.dataset.id===id));
  document.querySelectorAll('.arc').forEach(a=>a.classList.toggle('on',id==='hn'||a.dataset.id===id));
  card.classList.toggle('home-card',id==='hn');
  document.getElementById('ci').src=o.img; document.getElementById('ci').alt=o.flower+' từ '+o.country;
  document.getElementById('cc').textContent=o.country;
  document.getElementById('cf').textContent=o.flower;
  document.getElementById('cl').textContent=o.latin;
  document.getElementById('cr').textContent=o.region+' · '+o.coord;
  card.classList.remove('swap'); void card.offsetWidth; card.classList.add('swap');
}
document.querySelectorAll('.pin').forEach(p=>{
  p.addEventListener('mouseenter',()=>show(p.dataset.id));
  p.addEventListener('focus',()=>show(p.dataset.id));
  p.addEventListener('click',()=>{show(p.dataset.id);if(CODES[p.dataset.id])explain(p.dataset.id)});
  p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show(p.dataset.id);if(CODES[p.dataset.id])explain(p.dataset.id)}});
});
show('hn');
/* ===== HỘ CHIẾU HOA – gắn với đơn hàng =====
   Người làm web: đưa dữ liệu khách đang đăng nhập vào trang theo MỘT trong hai cách:
   (1) In sẵn vào trang (trong thẻ script):  window.LNT_PASSPORT = { loggedIn:true, name:"Minh Anh",
        stamps:[ {country:"ec", date:"2026-09-12", order:"#LNT1042"}, ... ] };
   (2) Hoặc đặt PASSPORT_CONFIG.api = "/api/ho-chieu-hoa" trả về JSON cùng định dạng trên.
   Mã nước: cn nl ec za jp my vn co nz. Chỉ đóng dấu khi đơn đã thanh toán & giao thành công. */
const PASSPORT_CONFIG={
  api:'',                                   // ví dụ '/api/ho-chieu-hoa'
  loginUrl:'/login', registerUrl:'/register',
  reward:'[Phần thưởng khi đủ 9 dấu – ví dụ: nâng hạng thành viên / tặng một Hộp hoa bí ẩn]',
  rewardLink:'/hop-hoa-bi-an',
  category:{cn:'/danh-muc/hoa-trung-quoc',nl:'/danh-muc/hoa-ha-lan',ec:'/danh-muc/hoa-ecuador',za:'/danh-muc/hoa-nam-phi',jp:'/danh-muc/hoa-nhat-ban',my:'/danh-muc/hoa-malaysia',vn:'/danh-muc/hoa-viet-nam',co:'/danh-muc/hoa-colombia',nz:'/danh-muc/hoa-new-zealand'},
  demo:true                                 // TẮT (false) khi đưa lên web thật
};
const CODES={cn:'KMG',nl:'AMS',ec:'UIO',za:'CPT',jp:'CTS',my:'KUL',vn:'DLI',co:'BOG',nz:'CHC'};
const ORDER=Object.keys(CODES);
const grid=document.getElementById('ppGrid'),tip=document.getElementById('ppTip');
let PP={loggedIn:false,stamps:[]};
const fmt=d=>{try{const x=new Date(d);return `${String(x.getDate()).padStart(2,'0')}.${String(x.getMonth()+1).padStart(2,'0')}.${x.getFullYear()}`}catch(e){return d}};
ORDER.forEach((id,i)=>{const b=document.createElement('button');b.type='button';b.className='st';b.dataset.id=id;b.textContent=CODES[id];
  b.style.setProperty('--r',((i*37)%21-10)+'deg');b.addEventListener('click',()=>{show(id);explain(id)});grid.appendChild(b)});
function stampOf(id){return (PP.stamps||[]).find(s=>s.country===id)}
function explain(id){const o=byId[id],s=stampOf(id),url=PASSPORT_CONFIG.category[id]||'#';
  if(!PP.loggedIn){tip.textContent='';return}
  tip.innerHTML=s?`Dấu <b>${CODES[id]}</b> · ${o.country}: nhận ngày ${fmt(s.date)}${s.order?` từ đơn ${s.order}`:''}.`
    :`Mua hoa ${o.country} để nhận dấu <b>${CODES[id]}</b>.`}
function render(animIds=[]){
  const have=new Set((PP.stamps||[]).map(s=>s.country).filter(x=>CODES[x]));
  grid.classList.toggle('locked',!PP.loggedIn);
  grid.querySelectorAll('.st').forEach(b=>{const id=b.dataset.id,on=PP.loggedIn&&have.has(id),s=stampOf(id);b.classList.toggle('on',on);
    b.setAttribute('aria-label',`${byId[id].country}: ${on?`đã có dấu, ngày ${fmt(s.date)}`:'chưa có dấu, mua hoa nước này để nhận'}`);
    b.title=on?`${byId[id].country} · ${fmt(s.date)}${s.order?' · '+s.order:''}`:`Mua hoa ${byId[id].country} để nhận dấu`;
    if(animIds.includes(id)){b.classList.remove('pop');void b.offsetWidth;b.classList.add('pop')}});
  const n=PP.loggedIn?have.size:0;document.getElementById('pp-count').textContent=`${n}/9`;
  document.getElementById('ppLogin').hidden=PP.loggedIn;
  document.getElementById('ppSub').textContent=PP.loggedIn?`${PP.name?PP.name+', mỗi':'Mỗi'} đơn hoa nhập từ một quốc gia sẽ được đóng dấu nước đó vào hộ chiếu khi đơn hoàn tất.`:'Sưu tập đủ dấu của chín vùng đất hoa bằng chính những đơn hoa bạn đặt.';
  const done=PP.loggedIn&&n===9,r=document.getElementById('ppReward');
  if(done){document.getElementById('ppText').textContent=PASSPORT_CONFIG.reward;document.getElementById('ppLink').href=PASSPORT_CONFIG.rewardLink}
  r.hidden=!done; if(!PP.loggedIn)tip.textContent='';
}
document.getElementById('ppLoginBtn').href=PASSPORT_CONFIG.loginUrl;if(PASSPORT_CONFIG.registerUrl)document.getElementById('ppRegBtn').href=PASSPORT_CONFIG.registerUrl;else document.getElementById('ppRegBtn').style.display='none';
const DEMO={out:{loggedIn:false,stamps:[]},
  mid:{loggedIn:true,name:'Minh Anh',stamps:[{country:'ec',date:'2026-02-12',order:'#LNT1042'},{country:'nl',date:'2026-03-08',order:'#LNT1107'},{country:'nz',date:'2026-05-20',order:'#LNT1264'},{country:'vn',date:'2026-07-02',order:'#LNT1311'},{country:'cn',date:'2026-09-14',order:'#LNT1398'}]},
  full:{loggedIn:true,name:'Minh Anh',stamps:ORDER.map((c,i)=>({country:c,date:`2026-${String(i+1).padStart(2,'0')}-15`,order:'#LNT'+(1001+i*37)}))}};
function load(d,anim){const prev=new Set((PP.stamps||[]).map(s=>s.country));PP=d||{loggedIn:false,stamps:[]};
  render(anim?(PP.stamps||[]).map(s=>s.country).filter(c=>!prev.has(c)):[])}
(async()=>{
  if(window.LNT_PASSPORT){load(window.LNT_PASSPORT,true);return}
  if(PASSPORT_CONFIG.api){try{const r=await fetch(PASSPORT_CONFIG.api,{credentials:'include'});if(r.ok){load(await r.json(),true);return}}catch(e){}}
  if(PASSPORT_CONFIG.demo){const dm=document.getElementById('ppDemo');dm.hidden=false;
    dm.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{load(DEMO[b.dataset.d],true);tip.textContent=''}));load(DEMO.mid,true)}
  else load(null,false);
})();
/* ===== Ảnh hộ chiếu để lưu / chia sẻ (khổ 1080x1350) ===== */
const SITE='lamnhienthao.com';
function rr(c,x,y,w,h,r){c.beginPath();c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+h,r);c.arcTo(x+w,y+h,x,y+h,r);c.arcTo(x,y+h,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath()}
function spaced(c,t,x,y,sp,align){const w=[...t].reduce((a,ch)=>a+c.measureText(ch).width+sp,0)-sp;let cx=align==='center'?x-w/2:x;for(const ch of t){c.fillText(ch,cx,y);cx+=c.measureText(ch).width+sp}}
async function passportImage(){
  try{await document.fonts.ready}catch(e){}
  const W=1080,H=1350,cv=document.createElement('canvas');cv.width=W;cv.height=H;const c=cv.getContext('2d');
  const SANS='"Josefin Sans","Avenir Next",sans-serif',SERIF='Lora,Georgia,serif';
  c.fillStyle='#F5EBE6';c.fillRect(0,0,W,H);
  c.fillStyle='#3A2C24';rr(c,70,70,W-140,H-140,48);c.fill();
  c.strokeStyle='rgba(226,174,132,.35)';c.lineWidth=2;rr(c,92,92,W-184,H-184,34);c.stroke();
  const lg=document.querySelector('.intro img');if(lg&&lg.complete){const lw=170,lh=lw*lg.naturalHeight/lg.naturalWidth;c.drawImage(lg,W/2-lw/2,140,lw,lh)}
  c.textBaseline='alphabetic';c.fillStyle='#E2AE84';c.font=`600 54px ${SANS}`;spaced(c,'HỘ CHIẾU HOA',W/2,380,10,'center');
  c.fillStyle='#BFA493';c.font=`400 26px ${SANS}`;spaced(c,'FLOWER PASSPORT',W/2,425,8,'center');
  const R=100,gx=[W/2-255,W/2,W/2+255],gy=[565,790,1015];
  ORDER.forEach((id,i)=>{const x=gx[i%3],y=gy[Math.floor(i/3)];c.save();c.translate(x,y);c.rotate(((i*37)%21-10)*Math.PI/180);
    const g=c.createRadialGradient(-30,-35,10,0,0,R);g.addColorStop(0,'#C98A66');g.addColorStop(1,'#9A5A40');c.fillStyle=g;c.beginPath();c.arc(0,0,R-14,0,7);c.fill();
    c.strokeStyle='#E2AE84';c.lineWidth=4;c.beginPath();c.arc(0,0,R-14,0,7);c.stroke();c.strokeStyle='rgba(246,227,211,.55)';c.lineWidth=2;c.beginPath();c.arc(0,0,R-26,0,7);c.stroke();
    c.fillStyle='#F6E3D3';c.textAlign='center';c.font=`600 40px ${SANS}`;c.fillText(CODES[id],0,10);
    c.font=`400 17px ${SANS}`;const n=byId[id].country.toUpperCase();c.fillText(n.length>14?n.slice(0,13)+'…':n,0,42);c.restore()});
  c.textAlign='left';c.fillStyle='#F4E8DC';c.font=`italic 400 38px ${SERIF}`;c.textAlign='center';c.fillText('Đã đi đủ chín vùng đất hoa',W/2,1180);
  const d=new Date();c.fillStyle='#BFA493';c.font=`400 22px ${SANS}`;c.textAlign='center';c.fillText(`${String(d.getDate()).padStart(2,'0')}.${String(d.getMonth()+1).padStart(2,'0')}.${d.getFullYear()}   ·   ${SITE}`,W/2,1228);
  return await new Promise(r=>cv.toBlob(r,'image/png'));
}
document.getElementById('ppSave').addEventListener('click',async e=>{const b=e.target;b.disabled=true;const old=b.textContent;b.textContent='Đang tạo ảnh…';
  try{const blob=await passportImage();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='ho-chieu-hoa-lam-nhien-thao.png';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);b.textContent='Đã lưu ✓'}
  catch(err){b.textContent='Chưa lưu được, hãy chụp màn hình'}setTimeout(()=>{b.textContent=old;b.disabled=false},2400)});
(function(){const sh=document.getElementById('ppShare');if(!navigator.share||!navigator.canShare)return;
  try{if(!navigator.canShare({files:[new File([new Blob(['x'])],'a.png',{type:'image/png'})]}))return}catch(e){return}
  sh.hidden=false;sh.addEventListener('click',async()=>{try{const blob=await passportImage();await navigator.share({files:[new File([blob],'ho-chieu-hoa.png',{type:'image/png'})],title:'Hộ chiếu hoa · Lâm Nhiên Thảo',text:'Mình đã đi đủ chín vùng đất hoa cùng Lâm Nhiên Thảo 🌸'})}catch(e){}})})();
</script>
@endpush
